_expandSkillCommand(text){if(!text.startsWith("/skill:"))return text;let spaceIndex=text.indexOf(" "),skillName=spaceIndex===-1?text.slice(7):text.slice(7,spaceIndex),args=spaceIndex===-1?"":text.slice(spaceIndex+1).trim(),skill=this.resourceLoader.getSkills().skills.find(s=>s.name===skillName);if(!skill)return text;try{let content=readFileSync8(skill.filePath,"utf-8"),body=stripFrontmatter(content).trim(),skillBlock=`<skill name="${skill.name}" location="${skill.filePath}">
References are relative to ${skill.baseDir}.

${body}
</skill>`;return args?`${skillBlock}

${args}`:skillBlock}catch(err){return this._extensionRunner.emitError({extensionPath:skill.filePath,event:"skill_expansion",error:err instanceof Error?err.message:String(err)}),text}}

